"use client";

import React, { useEffect, useState, useRef } from "react";
import { motion } from "framer-motion";
import {
  CheckCircle,
  XCircle,
  Clock,
  AlertCircle,
  Shield,
  RefreshCw,
  ChevronDown,
} from "lucide-react";
import { createClient } from "@supabase/supabase-js";
import StatusBanner from "@/components/StatusBanner";

interface StagingVaultRecord {
  id: string;
  patient_id: string;
  raw_payload: Record<string, unknown> | null;
  fhir_json: Record<string, unknown> | null;
  status: string;
  processed_at: string;
  conflict_flag?: boolean;
  ai_warning_msg?: string;
  model?: string;
  fallback_reason?: string;
}

export default function AdminPage() {
  const [records, setRecords] = useState<StagingVaultRecord[]>([]);
  const [selectedRecord, setSelectedRecord] = useState<StagingVaultRecord | null>(null);
  const [loading, setLoading] = useState(true);
  const [actionInProgress, setActionInProgress] = useState(false);
  const [actionStatus, setActionStatus] = useState<"idle" | "success" | "error">("idle");
  const [actionMessage, setActionMessage] = useState<string | null>(null);
  const [expandedErrors, setExpandedErrors] = useState(false);
  const supabaseRef = useRef<ReturnType<typeof createClient> | null>(null);
  // subscriptionRef holds the realtime channel object returned by Supabase.
  // Disable the explicit-any lint rule here because Supabase's channel type
  // is complex and not required for the surrounding logic.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const subscriptionRef = useRef<any>(null);

  // Initialize Supabase client
  useEffect(() => {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
    if (supabaseUrl && supabaseAnonKey) {
      supabaseRef.current = createClient(supabaseUrl, supabaseAnonKey);
    }
  }, []);

  // Fetch initial records and setup real-time subscription
  useEffect(() => {
    const fetchAndSubscribe = async () => {
      if (!supabaseRef.current) return;

      try {
        setLoading(true);

        // Fetch pending records (status = pending or processed, not rejected/approved)
        const { data, error } = await supabaseRef.current
          .from("staging_vault")
          .select("*")
          .in("status", ["pending", "processed"])
          .order("processed_at", { ascending: false });

        if (error) {
          console.error("❌ Error fetching records:", error);
        } else {
          console.log("📋 [ADMIN] Loaded records:", data?.length || 0);
          setRecords(data || []);
          if (data && data.length > 0) {
            setSelectedRecord(data[0]);
          }
        }

        // Setup real-time subscription for new records
        const channel = supabaseRef.current
          .channel("staging_vault_changes")
          .on(
            "postgres_changes",
            {
              event: "*",
              schema: "public",
              table: "staging_vault",
              filter: `status=in.(pending,processed)`,
            },
            (payload) => {
              console.log("🔔 [ADMIN] Real-time update:", payload.eventType);

              if (payload.eventType === "INSERT") {
                setRecords((prev) => [payload.new as StagingVaultRecord, ...prev]);
              } else if (payload.eventType === "UPDATE") {
                setRecords((prev) =>
                  prev.map((r) =>
                    r.id === payload.new.id
                      ? (payload.new as StagingVaultRecord)
                      : r
                  )
                );
                if (selectedRecord?.id === payload.new.id) {
                  setSelectedRecord(payload.new as StagingVaultRecord);
                }
              } else if (payload.eventType === "DELETE") {
                setRecords((prev) => prev.filter((r) => r.id !== payload.old.id));
                if (selectedRecord?.id === payload.old.id) {
                  setSelectedRecord(null);
                }
              }
            }
          )
          .subscribe((status) => {
            console.log(`[ADMIN] Subscription status: ${status}`);
          });

        subscriptionRef.current = channel;
      } catch (error) {
        console.error("Setup error:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchAndSubscribe();

    return () => {
      if (subscriptionRef.current) {
        supabaseRef.current?.removeChannel(subscriptionRef.current);
      }
    };
  }, []);

  const handleApprove = async () => {
    if (!selectedRecord) return;

    setActionInProgress(true);
    setActionStatus("idle");
    setActionMessage(null);

    try {
      console.log(`✅ [ADMIN] Approving: ${selectedRecord.id}`);

      const response = await fetch("http://localhost:8000/admin/resolve-pr", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-API-Key": "vault-test-key-do-not-use-in-production",
        },
        body: JSON.stringify({
          staging_id: selectedRecord.id,
          decision: "approve",
          admin_id: "admin-dashboard-user",
          reason: "Approved via admin dashboard",
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setActionStatus("success");
        setActionMessage(`✅ Approved! TX: ${data.tx_id}`);
        setRecords((prev) => prev.filter((r) => r.id !== selectedRecord.id));
        setSelectedRecord(null);
      } else {
        setActionStatus("error");
        setActionMessage(`❌ ${data.detail}`);
      }
    } catch (error) {
      setActionStatus("error");
      setActionMessage(
        `❌ ${error instanceof Error ? error.message : "Unknown error"}`
      );
    } finally {
      setActionInProgress(false);
    }
  };

  const handleReject = async () => {
    if (!selectedRecord) return;

    setActionInProgress(true);
    setActionStatus("idle");
    setActionMessage(null);

    try {
      console.log(`❌ [ADMIN] Rejecting: ${selectedRecord.id}`);

      const response = await fetch("http://localhost:8000/admin/resolve-pr", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-API-Key": "vault-test-key-do-not-use-in-production",
        },
        body: JSON.stringify({
          staging_id: selectedRecord.id,
          decision: "reject",
          admin_id: "admin-dashboard-user",
          reason: selectedRecord.fallback_reason || "Rejected via admin dashboard",
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setActionStatus("success");
        setActionMessage(`✅ Rejected. TX: ${data.tx_id}`);
        setRecords((prev) => prev.filter((r) => r.id !== selectedRecord.id));
        setSelectedRecord(null);
      } else {
        setActionStatus("error");
        setActionMessage(`❌ ${data.detail}`);
      }
    } catch (error) {
      setActionStatus("error");
      setActionMessage(
        `❌ ${error instanceof Error ? error.message : "Unknown error"}`
      );
    } finally {
      setActionInProgress(false);
    }
  };

  const handleManualRefresh = async () => {
    console.log("🔄 Manual refresh triggered");
    setLoading(true);
    try {
      const { data, error } = await supabaseRef.current!
        .from("staging_vault")
        .select("*")
        .in("status", ["pending", "processed"])
        .order("processed_at", { ascending: false });

      if (error) {
        console.error("Error:", error);
      } else {
        console.log("✅ Refreshed:", data?.length || 0);
        setRecords(data || []);
      }
    } finally {
      setLoading(false);
    }
  };

  // Parse error info from ai_warning_msg or fallback_reason
  const parseErrorInfo = (record: StagingVaultRecord) => {
    const messages: string[] = [];
    if (record.ai_warning_msg) messages.push(`⚠️ ${record.ai_warning_msg}`);
    if (record.fallback_reason) messages.push(`🔄 ${record.fallback_reason}`);
    return messages;
  };

  return (
    <div className="min-h-screen bg-slate-50 px-4 py-10 sm:px-8">
      <div className="mx-auto w-full max-w-7xl space-y-6">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="rounded-3xl bg-white p-8 shadow-[0_30px_60px_-40px_rgba(15,23,42,0.35)]"
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-emerald-600 text-white">
                <Shield size={24} />
              </div>
              <div>
                <p className="text-xs font-semibold uppercase tracking-[0.2em] text-slate-400">
                  Module 4 - Admin Triage
                </p>
                <h1 className="text-2xl font-extrabold text-slate-900">
                  Clinical Record Review Queue
                </h1>
              </div>
            </div>
            <button
              onClick={handleManualRefresh}
              disabled={loading}
              className="inline-flex items-center gap-2 rounded-lg bg-slate-100 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-200 disabled:opacity-50"
            >
              <RefreshCw size={16} className={loading ? "animate-spin" : ""} />
              Refresh
            </button>
          </div>
          <p className="mt-4 text-sm text-slate-600">
            Review AI-processed clinical records with full before/after comparison
          </p>
        </motion.div>

        <div className="grid gap-6 lg:grid-cols-3">
          {/* Queue Sidebar */}
          <motion.div
            initial={{ opacity: 0, x: -16 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="lg:col-span-1"
          >
            <div className="rounded-3xl bg-white p-6 shadow-[0_30px_60px_-40px_rgba(15,23,42,0.35)]">
              <h2 className="text-sm font-bold uppercase tracking-[0.15em] text-slate-600">
                Pending Queue ({records.length})
              </h2>

              {loading ? (
                <div className="mt-4 space-y-2">
                  {[...Array(3)].map((_, i) => (
                    <div
                      key={i}
                      className="h-16 animate-pulse rounded-lg bg-slate-100"
                    />
                  ))}
                </div>
              ) : records.length === 0 ? (
                <div className="mt-4 text-center rounded-lg border border-slate-200 bg-slate-50 p-6">
                  <CheckCircle size={32} className="mx-auto text-emerald-500" />
                  <p className="mt-2 text-sm font-semibold text-slate-700">
                    Queue Empty
                  </p>
                </div>
              ) : (
                <div className="mt-4 max-h-[600px] space-y-2 overflow-y-auto">
                  {records.map((record) => {
                    const errors = parseErrorInfo(record);
                    const hasErrors = errors.length > 0;

                    return (
                      <motion.button
                        key={record.id}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        onClick={() => setSelectedRecord(record)}
                        className={`w-full rounded-lg border-2 p-3 text-left transition ${
                          selectedRecord?.id === record.id
                            ? "border-emerald-500 bg-emerald-50"
                            : "border-slate-200 bg-white hover:border-slate-300"
                        }`}
                      >
                        <div className="flex items-start justify-between gap-2">
                          <div className="min-w-0 flex-1">
                            <div className="text-sm font-semibold text-slate-900">
                              {record.patient_id}
                            </div>
                            <div className="mt-1 flex items-center gap-1 text-xs text-slate-600">
                              <Clock size={12} />
                              {new Date(record.processed_at).toLocaleTimeString()}
                            </div>
                            {hasErrors && (
                              <div className="mt-2 space-y-1">
                                {errors.map((err, i) => (
                                  <div
                                    key={i}
                                    className="text-xs text-amber-600 truncate"
                                  >
                                    {err}
                                  </div>
                                ))}
                              </div>
                            )}
                          </div>
                          {record.conflict_flag && (
                            <AlertCircle size={16} className="text-red-600 flex-shrink-0" />
                          )}
                        </div>
                      </motion.button>
                    );
                  })}
                </div>
              )}
            </div>
          </motion.div>

          {/* Details & Comparison View */}
          <motion.div
            initial={{ opacity: 0, x: 16 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="lg:col-span-2"
          >
            <div className="rounded-3xl bg-white p-8 shadow-[0_30px_60px_-40px_rgba(15,23,42,0.35)]">
              {!selectedRecord ? (
                <div className="flex h-96 items-center justify-center">
                  <p className="text-slate-600">
                    {loading ? "Loading records..." : "Select a record to review"}
                  </p>
                </div>
              ) : (
                <div className="space-y-6">
                  {/* Record Header */}
                  <div>
                    <h3 className="text-lg font-bold text-slate-900">
                      Patient: {selectedRecord.patient_id}
                    </h3>
                    <div className="mt-3 flex flex-wrap gap-3">
                      <span className="inline-flex items-center gap-1 rounded-full bg-blue-50 px-3 py-1 text-xs font-semibold text-blue-700">
                        <Clock size={12} />
                      {new Date(selectedRecord.processed_at).toLocaleString()}
                      </span>
                      <span className="inline-flex items-center gap-1 rounded-full bg-purple-50 px-3 py-1 text-xs font-semibold text-purple-700">
                        Model: {selectedRecord.model || "unknown"}
                      </span>
                      {selectedRecord.conflict_flag && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-red-50 px-3 py-1 text-xs font-semibold text-red-700">
                          <AlertCircle size={12} />
                          Conflict Detected
                        </span>
                      )}
                      {selectedRecord.status === "processed" && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-green-50 px-3 py-1 text-xs font-semibold text-green-700">
                          ✅ Processed & Ready
                        </span>
                      )}
                    </div>
                  </div>

                  {/* Error Messages */}
                  {(selectedRecord.ai_warning_msg || selectedRecord.fallback_reason) && (
                    <div className="rounded-lg border border-amber-200 bg-amber-50 p-4">
                      <button
                        onClick={() => setExpandedErrors(!expandedErrors)}
                        className="flex w-full items-center justify-between text-left"
                      >
                        <span className="font-semibold text-amber-900">
                          ⚠️ Processing Issues
                        </span>
                        <ChevronDown
                          size={16}
                          className={`transition ${expandedErrors ? "rotate-180" : ""}`}
                        />
                      </button>
                      {expandedErrors && (
                        <div className="mt-3 space-y-2 border-t border-amber-200 pt-3">
                          {selectedRecord.ai_warning_msg && (
                            <div className="text-sm text-amber-800">
                              <strong>AI Warning:</strong> {selectedRecord.ai_warning_msg}
                            </div>
                          )}
                          {selectedRecord.fallback_reason && (
                            <div className="text-sm text-amber-800">
                              <strong>Fallback Reason:</strong> {selectedRecord.fallback_reason}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  )}

                  {/* Before/After Comparison */}
                  <div>
                    <h4 className="mb-3 text-sm font-bold uppercase tracking-[0.15em] text-slate-600">
                      Before/After Clinical Data
                    </h4>
                    <div className="grid gap-3 lg:grid-cols-2">
                      {/* Before (Raw Payload) */}
                      <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
                        <p className="mb-2 text-xs font-semibold text-slate-600">
                          📥 Input (Raw)
                        </p>
                        <pre className="max-h-64 overflow-auto text-xs text-slate-700">
                          {selectedRecord.raw_payload
                            ? JSON.stringify(selectedRecord.raw_payload, null, 2)
                            : "(empty)"}
                        </pre>
                      </div>

                      {/* After (FHIR JSON) */}
                      <div className="rounded-lg border border-slate-200 bg-emerald-50 p-4">
                        <p className="mb-2 text-xs font-semibold text-slate-600">
                          📤 Output (FHIR)
                        </p>
                        <pre className="max-h-64 overflow-auto text-xs text-slate-700">
                          {selectedRecord.fhir_json
                            ? JSON.stringify(selectedRecord.fhir_json, null, 2)
                            : "(empty or processing)"}
                        </pre>
                      </div>
                    </div>
                  </div>

                  {/* Status Messages */}
                  {actionStatus !== "idle" && (
                    <StatusBanner
                      variant={actionStatus}
                      title={
                        actionStatus === "success"
                          ? "Action Successful"
                          : "Action Failed"
                      }
                      description={actionMessage || ""}
                    />
                  )}

                  {/* Action Buttons */}
                  <div className="flex gap-3 pt-4">
                    <button
                      onClick={handleApprove}
                      disabled={actionInProgress || selectedRecord.status !== "processed"}
                      className="flex-1 rounded-lg bg-emerald-600 px-4 py-3 font-semibold text-white transition hover:bg-emerald-700 disabled:opacity-50"
                    >
                      {actionInProgress ? (
                        "Processing..."
                      ) : (
                        <>
                          <CheckCircle className="mr-2 inline" size={18} />
                          Approve & Commit
                        </>
                      )}
                    </button>
                    <button
                      onClick={handleReject}
                      disabled={actionInProgress}
                      className="flex-1 rounded-lg bg-red-600 px-4 py-3 font-semibold text-white transition hover:bg-red-700 disabled:opacity-50"
                    >
                      {actionInProgress ? (
                        "Processing..."
                      ) : (
                        <>
                          <XCircle className="mr-2 inline" size={18} />
                          Reject
                        </>
                      )}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </motion.div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { createClient } from '@/lib/supabase-client';
import { Mail, Lock, Loader2, AlertCircle, CheckCircle2 } from 'lucide-react';
import demoConfig from '@/../../demouser.json';

type AuthStep = 'email-role' | 'otp-input' | 'loading';

interface FormState {
  email: string;
  role: 'doctor' | 'admin' | 'patient';
  otp: string;
  error: string | null;
  showOtpInput: boolean;
  isDemoMode?: boolean;
}

export default function LoginPage() {
  const router = useRouter();
  const supabase = createClient();
  
  const [step, setStep] = useState<AuthStep>('email-role');
  const [form, setForm] = useState<FormState>({
    email: '',
    role: 'patient',
    otp: '',
    error: null,
    showOtpInput: false,
    isDemoMode: false,
  });
  const [loading, setLoading] = useState(false);
  const [sessionEmail, setSessionEmail] = useState<string>('');

  const redirectByRole = (role: string) => {
    switch (role) {
      case 'admin':
        router.push('/admin');
        break;
      case 'doctor':
        router.push('/dashboard');
        break;
      case 'patient':
      default:
        router.push('/patient');
    }
  };

  // Check if user is already logged in
  useEffect(() => {
    const checkSession = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        // User is logged in, fetch their role
        const { data: roleData } = await supabase
          .from('user_roles')
          .select('role')
          .eq('user_id', user.id)
          .maybeSingle();

        const role = (roleData as { role?: string } | null)?.role ?? 'patient';
        redirectByRole(role);
      }
    };

    checkSession();
  }, [router, supabase]);

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!form.email.trim()) {
      setForm(prev => ({ ...prev, error: 'Email is required' }));
      return;
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(form.email)) {
      setForm(prev => ({ ...prev, error: 'Please enter a valid email address' }));
      return;
    }

    // ✨ DEMO MODE: Check if this is a demo user
    const isDemoUser = demoConfig.demo_users.includes(form.email);
    
    if (isDemoUser) {
      console.log('🎭 Demo mode engaged for:', form.email);
      // Instantly show OTP input without calling Supabase
      setSessionEmail(form.email);
      setForm(prev => ({
        ...prev,
        showOtpInput: true,
        isDemoMode: true,
        error: null,
      }));
      return;
    }

    setLoading(true);
    setForm(prev => ({ ...prev, error: null, isDemoMode: false }));

    try {
      // Send real OTP via Supabase
      const { error } = await supabase.auth.signInWithOtp({
        email: form.email,
        options: {
          emailRedirectTo: `${process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000'}/auth/callback`,
        },
      });

      if (error) {
        throw new Error(error.message);
      }

      // OTP sent successfully
      setSessionEmail(form.email);
      setForm(prev => ({
        ...prev,
        showOtpInput: true,
        isDemoMode: false,
        error: null,
      }));

    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      setForm(prev => ({
        ...prev,
        error: message || 'Failed to send OTP. Please try again.',
      }));
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!form.otp || form.otp.length !== 6) {
      setForm(prev => ({ ...prev, error: 'Please enter a valid 6-digit PIN' }));
      return;
    }

    setLoading(true);
    setForm(prev => ({ ...prev, error: null }));

    try {
      let authData: unknown = null;
      
      // ✨ DEMO MODE: If demo user enters 123456, use password auth
      if (form.isDemoMode && form.otp === demoConfig.demo_pin) {
        console.log('🎭 Demo mode: using password authentication');
        const demoPassword = demoConfig.hidden_password_prefix + demoConfig.demo_pin;
        
        const { data, error } = await supabase.auth.signInWithPassword({
          email: sessionEmail,
          password: demoPassword,
        });

        if (error) {
          throw new Error(error.message || 'Invalid PIN. Please try again.');
        }

        authData = data;
      } else if (form.isDemoMode) {
        // Demo user but wrong PIN
        throw new Error('Invalid PIN. For demo mode, use: ' + demoConfig.demo_pin);
      } else {
        // Real OTP verification
        const { data, error } = await supabase.auth.verifyOtp({
          email: sessionEmail,
          token: form.otp,
          type: 'email',
        });

        if (error) {
          throw new Error(error.message);
        }

        authData = data;
      }

        const user = (authData as { user?: { id: string } } | null)?.user;
        if (user) {
        setStep('loading');

        // Fetch user role
        const { data: roleData, error: roleError } = await supabase
          .from('user_roles')
          .select('role')
          .eq('user_id', user.id)
          .maybeSingle();

        if (roleError) {
          throw new Error('Unable to fetch user role. Please contact support.');
        }

        // Redirect by role
        const userRole = (roleData as { role?: string } | null)?.role ?? 'patient';
        redirectByRole(userRole);
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      setForm(prev => ({
        ...prev,
        error: message || 'Invalid PIN. Please try again.',
        otp: '',
      }));
    } finally {
      setLoading(false);
    }
  };

  const handleBackToEmail = () => {
    setForm(prev => ({
      ...prev,
      showOtpInput: false,
      otp: '',
      error: null,
    }));
    setSessionEmail('');
  };

  // Loading screen
  if (step === 'loading') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-blue-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-700 font-semibold">Completing authentication...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
      <div className="w-full max-w-md">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-12 h-12 bg-blue-600 text-white rounded-lg mb-4">
            <Lock className="w-6 h-6" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900">Memory Vault</h1>
          <p className="text-gray-600 mt-2">Secure Medical Data Access</p>
        </div>

        {/* Main Card */}
        <div className="bg-white rounded-lg shadow-xl p-8">
          {!form.showOtpInput ? (
            // STEP 1: Email & Role Selection
            <form onSubmit={handleSendOtp} className="space-y-6">
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                  Email Address
                </label>
                <div className="relative">
                  <Mail className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                  <input
                    id="email"
                    type="email"
                    value={form.email}
                    onChange={(e) =>
                      setForm(prev => ({ ...prev, email: e.target.value, error: null }))
                    }
                    placeholder="you@hospital.com"
                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                    disabled={loading}
                  />
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  Your registered hospital email address
                </p>
              </div>

              <div>
                <label htmlFor="role" className="block text-sm font-medium text-gray-700 mb-2">
                  User Role
                </label>
                <select
                  id="role"
                  value={form.role}
                  onChange={(e) =>
                    setForm(prev => ({ ...prev, role: e.target.value as FormState['role'] }))
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                  disabled={loading}
                >
                  <option value="patient">Patient</option>
                  <option value="doctor">Doctor / Clinician</option>
                  <option value="admin">Administrator</option>
                </select>
                <p className="text-xs text-gray-500 mt-1">
                  Your role in the system (must be pre-provisioned)
                </p>
              </div>

              {/* Error Message */}
              {form.error && (
                <div className="flex items-start gap-3 p-4 bg-red-50 border border-red-200 rounded-lg">
                  <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                  <p className="text-sm text-red-700">{form.error}</p>
                </div>
              )}

              {/* Send OTP Button */}
              <button
                type="submit"
                disabled={loading}
                className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-semibold py-2 px-4 rounded-lg transition flex items-center justify-center gap-2"
              >
                {loading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Sending OTP...
                  </>
                ) : (
                  <>
                    <Mail className="w-4 h-4" />
                    Send Secure OTP
                  </>
                )}
              </button>

              <p className="text-xs text-gray-500 text-center">
                A 6-digit PIN will be sent to your email
              </p>
            </form>
          ) : (
            // STEP 2: OTP Verification
            <form onSubmit={handleVerifyOtp} className="space-y-6">
              <div className={`flex items-center justify-center p-4 rounded-lg ${form.isDemoMode ? 'bg-purple-50' : 'bg-blue-50'}`}>
                <CheckCircle2 className={`w-5 h-5 ${form.isDemoMode ? 'text-purple-600' : 'text-blue-600'} mr-2`} />
                <p className={`text-sm ${form.isDemoMode ? 'text-purple-700' : 'text-blue-700'}`}>
                  {form.isDemoMode ? '🎭 Demo Mode' : 'PIN sent to'} <strong>{sessionEmail}</strong>
                </p>
              </div>

              <div>
                <label htmlFor="otp" className="block text-sm font-medium text-gray-700 mb-2">
                  Enter 6-Digit PIN
                </label>
                <input
                  id="otp"
                  type="text"
                  value={form.otp}
                  onChange={(e) => {
                    const value = e.target.value.replace(/\D/g, '').slice(0, 6);
                    setForm(prev => ({ ...prev, otp: value, error: null }));
                  }}
                  placeholder="000000"
                  maxLength={6}
                  className="w-full px-4 py-3 text-center text-2xl font-mono border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                  disabled={loading}
                  autoComplete="one-time-code"
                />
                <p className="text-xs text-gray-500 mt-1 text-center">
                  Check your email for the PIN
                </p>
              </div>

              {/* Error Message */}
              {form.error && (
                <div className="flex items-start gap-3 p-4 bg-red-50 border border-red-200 rounded-lg">
                  <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                  <p className="text-sm text-red-700">{form.error}</p>
                </div>
              )}

              {/* Verify Button */}
              <button
                type="submit"
                disabled={loading || form.otp.length !== 6}
                className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-semibold py-2 px-4 rounded-lg transition flex items-center justify-center gap-2"
              >
                {loading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Verifying...
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="w-4 h-4" />
                    Verify PIN
                  </>
                )}
              </button>

              {/* Back Button */}
              <button
                type="button"
                onClick={handleBackToEmail}
                disabled={loading}
                className="w-full bg-gray-100 hover:bg-gray-200 disabled:bg-gray-100 text-gray-700 font-semibold py-2 px-4 rounded-lg transition"
              >
                Back to Email
              </button>

              <p className="text-xs text-gray-500 text-center">
                Didn&apos;t receive the PIN? Check spam folder or request a new one
              </p>
            </form>
          )}
        </div>

        {/* Footer Info */}
        <div className="mt-6 text-center text-xs text-gray-600">
          <p>
            🔒 This system uses production-grade Supabase Authentication
          </p>
          <p className="mt-2">
            For pre-provisioned users only. Contact your administrator.
          </p>
        </div>
      </div>
    </div>
  );
}
